import json, sys
sys.path.insert(0, "/app/tmp/t")
from run import run_json

def CFG(**kw):
    c = {
        "early": False, "overlap": "reject", "buffer_packets": 2, "idle_ms": 0,
        "max_streams_bidi": 4, "max_streams_uni": 4, "max_stream_data": 32,
        "max_data": 64, "crypto_limit": 32,
        "sent": {"I": [], "H": [], "A": []},
    }
    c.update(kw); return c

def key(t, level, action): return {"t": t, "op": "key", "level": level, "action": action}
def tick(t): return {"t": t, "op": "tick"}
def dg(t, size, pkts): return {"t": t, "op": "datagram", "bytes": size, "packets": pkts}
def pkt(level, pn, auth, frames): return {"level": level, "pn": pn, "auth": auth, "frames": frames}
def PAD(): return {"type": "PADDING"}
def PING(): return {"type": "PING"}
def ACK(*ranges): return {"type": "ACK", "ranges": [list(r) for r in ranges]}
def CRY(off, hx): return {"type": "CRYPTO", "offset": off, "data_hex": hx}
def STR(sid, off, hx, fin): return {"type": "STREAM", "id": sid, "offset": off, "data_hex": hx, "fin": fin}
def RST(sid, fs): return {"type": "RESET_STREAM", "id": sid, "final_size": fs}
def STOP(sid): return {"type": "STOP_SENDING", "id": sid}
def CLOSE(app, code): return {"type": "CLOSE", "app": app, "code": code}
def HD(): return {"type": "HANDSHAKE_DONE"}
def UNK(): return {"type": "UNKNOWN"}

def pres(e, p, status, reason, at, frame=None):
    return {"event": e, "packet": p, "status": status, "reason": reason, "at_ms": at, "frame": frame}

def conn_open(last=0):
    return {"state": "open", "code": None, "at_ms": None, "source": None,
            "peer_code": None, "last_activity_ms": last}

def conn_closed(code, at, src, last=0, peer=None):
    return {"state": "closed", "code": code, "at_ms": at, "source": src,
            "peer_code": peer, "last_activity_ms": last}

def conn_idle(at, src, last=0):
    return {"state": "idle", "code": "IDLE_TIMEOUT", "at_ms": at, "source": src,
            "peer_code": None, "last_activity_ms": last}

def src(e, p=None, f=None): return {"event": e, "packet": p, "frame": f}

def KEYS(i="live", h="absent", z="absent", a="absent"):
    return {"I": i, "H": h, "Z": z, "A": a}

def st(sid, highest, fs=None, reset=False, stopped=False, hx=""):
    return {"id": sid, "highest": highest, "final_size": fs, "reset": reset,
            "stopped": stopped, "delivered_hex": hx}

def cr(level, highest, hx=""):
    return {"level": level, "highest": highest, "contiguous_hex": hx}

def RES(id, packets, conn, keys, rt, streams, crypto):
    return {"id": id, "packets": packets, "connection": conn, "keys": keys,
            "received_total": rt, "streams": streams, "crypto": crypto}

def check(name, cfg, events, expected, traces_id="t"):
    req = {"version": 1, "traces": [{"id": traces_id, "config": cfg, "events": events}]}
    rc, out, err = run_json(req)
    try:
        got = json.loads(out)
    except Exception:
        got = ("UNPARSEABLE", out[:400], err[:400])
    want = {"version": 1, "results": [expected]}
    ok = (rc == 0 and got == want)
    print(("PASS " if ok else "FAIL ") + name)
    if not ok:
        print("  got     :", json.dumps(got)[:2000])
        print("  expected:", json.dumps(want)[:2000])
    return ok
PYEOF
echo ok
